import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Card, Button, Table, Form, Modal } from 'react-bootstrap';
import { apiService } from '../services/api';
import { useAuth } from '../contexts/AuthContext';
import LoadingSpinner from '../components/LoadingSpinner';
import Toast from '../components/Toast';

interface ReturnItem {
  date_acquired: string;
  qty: number;
  unit: string;
  property_no: string;
  description: string;
  amount: number;
}

interface PropertyReturn {
  id?: string;
  prs_no: string;
  entity_name: string;
  return_type: 'Unserviceable' | 'No longer needed' | 'Reassignment' | 'Others';
  return_type_others?: string;
  items: ReturnItem[];
  returned_by: string;
  returned_by_designation: string;
  returned_by_office: string;
  returned_date: string;
  received_by: string;
  noted_by: string;
  status: 'Draft' | 'Submitted';
}

const PropertyReturnSlip: React.FC = () => {
  const { user } = useAuth();
  const [returns, setReturns] = useState<PropertyReturn[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [showModal, setShowModal] = useState(false);
  const [showViewModal, setShowViewModal] = useState(false);
  const [selectedReturn, setSelectedReturn] = useState<PropertyReturn | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [toastMessage, setToastMessage] = useState('');
  const [toastType, setToastType] = useState<'success' | 'error' | 'warning' | 'info'>('info');
  const [showToast, setShowToast] = useState(false);

  const [currentReturn, setCurrentReturn] = useState<PropertyReturn>({
    prs_no: '',
    entity_name: '',
    return_type: 'Unserviceable',
    return_type_others: '',
    items: [],
    returned_by: user?.full_name || '',
    returned_by_designation: '',
    returned_by_office: '',
    returned_date: new Date().toISOString().split('T')[0],
    received_by: '',
    noted_by: '',
    status: 'Draft'
  });

  const [newItem, setNewItem] = useState<ReturnItem>({
    date_acquired: '',
    qty: 0,
    unit: '',
    property_no: '',
    description: '',
    amount: 0
  });

  useEffect(() => {
    fetchPropertyReturns();
  }, []);

  const fetchPropertyReturns = async () => {
    try {
      setLoading(true);
      setError(null);
      const data = await apiService.getPropertyReturnSlips();
      setReturns(data || []);
    } catch (err) {
      setError('Failed to load property return slips');
      console.error(err);
      setReturns([]);
    } finally {
      setLoading(false);
    }
  };

  const handleAddItem = () => {
    if (!newItem.date_acquired || !newItem.property_no || !newItem.description) {
      setToastMessage('Please fill in required item fields');
      setToastType('warning');
      setShowToast(true);
      return;
    }

    setCurrentReturn({
      ...currentReturn,
      items: [...currentReturn.items, newItem]
    });

    setNewItem({
      date_acquired: '',
      qty: 0,
      unit: '',
      property_no: '',
      description: '',
      amount: 0
    });
  };

  const handleRemoveItem = (index: number) => {
    setCurrentReturn({
      ...currentReturn,
      items: currentReturn.items.filter((_, i) => i !== index)
    });
  };

  const handleSave = async () => {
    try {
      if (!currentReturn.prs_no || !currentReturn.entity_name) {
        setToastMessage('Please fill in all required fields');
        setToastType('warning');
        setShowToast(true);
        return;
      }

      if (currentReturn.items.length === 0) {
        setToastMessage('Please add at least one item');
        setToastType('warning');
        setShowToast(true);
        return;
      }

      if (!currentReturn.received_by || !currentReturn.noted_by) {
        setToastMessage('Please fill in Received By and Noted By fields');
        setToastType('warning');
        setShowToast(true);
        return;
      }

      setToastMessage('Property Return Slip saved successfully');
      setToastType('success');
      setShowToast(true);
      setShowModal(false);
      fetchPropertyReturns();
    } catch (err) {
      setToastMessage('Failed to save property return slip');
      setToastType('error');
      setShowToast(true);
    }
  };

  const filteredReturns = returns.filter(ret =>
    ret.prs_no.toLowerCase().includes(searchTerm.toLowerCase()) ||
    ret.entity_name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (loading) return <LoadingSpinner size="lg" text="Loading Property Return Slips..." />;

  return (
    <Container fluid className="py-4">
      {error && (
        <Row className="mb-3">
          <Col>
            <div className="alert alert-danger">{error}</div>
          </Col>
        </Row>
      )}

      {/* Header Section */}
      <Row className="mb-4 align-items-center">
        <Col md={6}>
          <h2 className="mb-0">Property Return Slip</h2>
          <p className="text-muted">Manage and track property returns</p>
        </Col>
        <Col md={6} className="text-end">
          <Button
            variant="primary"
            onClick={() => {
              setCurrentReturn({
                prs_no: '',
                entity_name: '',
                fund_cluster: '',
                return_reason: 'Damaged',
                return_reason_others: '',
                items: [],
                approved_by: '',
                released_issued_by: user?.full_name || '',
                received_by: '',
                date: new Date().toISOString().split('T')[0],
                status: 'Draft'
              });
              setNewItem({
                date_acquired: '',
                item_no: '',
                ics_no: '',
                description: '',
                amount: 0,
                condition: 'Good'
              });
              setShowModal(true);
            }}
          >
            <i className="bi bi-plus-circle me-2"></i>
            New Return
          </Button>
        </Col>
      </Row>

      {/* Search Section */}
      <Row className="mb-4">
        <Col md={12}>
          <Form.Group>
            <Form.Control
              placeholder="Search by PRS No. or Entity Name..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </Form.Group>
        </Col>
      </Row>

      {/* Table Section */}
      <Row>
        <Col md={12}>
          <Card className="shadow-sm">
            <Card.Body>
              <div className="table-responsive">
                <Table striped hover>
                  <thead>
                    <tr>
                      <th>PRS No.</th>
                      <th>Entity Name</th>
                      <th>Return Type</th>
                      <th>Items</th>
                      <th>Returned Date</th>
                      <th>Status</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    {filteredReturns.length > 0 ? (
                      filteredReturns.map((ret) => (
                        <tr key={ret.id}>
                          <td>{ret.prs_no}</td>
                          <td>{ret.entity_name}</td>
                          <td>{ret.return_type}</td>
                          <td>{ret.items.length}</td>
                          <td>{ret.returned_date}</td>
                          <td>
                            <span className={`badge bg-${ret.status === 'Submitted' ? 'success' : 'warning'}`}>
                              {ret.status}
                            </span>
                          </td>
                          <td>
                            <Button
                              variant="info"
                              size="sm"
                              onClick={() => {
                                setSelectedReturn(ret);
                                setShowViewModal(true);
                              }}
                            >
                              <i className="bi bi-eye"></i> View
                            </Button>
                          </td>
                        </tr>
                      ))
                    ) : (
                      <tr>
                        <td colSpan={7} className="text-center py-4">
                          No property return slips found
                        </td>
                      </tr>
                    )}
                  </tbody>
                </Table>
              </div>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Create/Edit Modal */}
      <Modal show={showModal} onHide={() => setShowModal(false)} size="lg">
        <Modal.Header closeButton>
          <Modal.Title>Create Property Return Slip</Modal.Title>
        </Modal.Header>
        <Modal.Body>
          <Form>
            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>PRS No. *</Form.Label>
                  <Form.Control
                    value={currentReturn.prs_no}
                    onChange={(e) => setCurrentReturn({ ...currentReturn, prs_no: e.target.value })}
                    placeholder="Enter PRS No."
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Entity Name *</Form.Label>
                  <Form.Control
                    value={currentReturn.entity_name}
                    onChange={(e) => setCurrentReturn({ ...currentReturn, entity_name: e.target.value })}
                    placeholder="Enter Entity Name"
                  />
                </Form.Group>
              </Col>
            </Row>

            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Fund Cluster</Form.Label>
                  <Form.Control
                    value={currentReturn.fund_cluster}
                    onChange={(e) => setCurrentReturn({ ...currentReturn, fund_cluster: e.target.value })}
                    placeholder="Enter Fund Cluster"
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Return Reason *</Form.Label>
                  <Form.Select
                    value={currentReturn.return_reason}
                    onChange={(e) => setCurrentReturn({ ...currentReturn, return_reason: e.target.value as any })}
                  >
                    <option value="Damaged">Damaged</option>
                    <option value="Obsolete">Obsolete</option>
                    <option value="Returned to Supplier">Returned to Supplier</option>
                    <option value="Others">Others</option>
                  </Form.Select>
                </Form.Group>
              </Col>
            </Row>

            {currentReturn.return_reason === 'Others' && (
              <Form.Group className="mb-3">
                <Form.Label>Please Specify</Form.Label>
                <Form.Control
                  value={currentReturn.return_reason_others || ''}
                  onChange={(e) => setCurrentReturn({ ...currentReturn, return_reason_others: e.target.value })}
                  placeholder="Specify other reason"
                />
              </Form.Group>
            )}

            <Row>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Released/Issued By</Form.Label>
                  <Form.Control
                    value={currentReturn.released_issued_by}
                    onChange={(e) => setCurrentReturn({ ...currentReturn, released_issued_by: e.target.value })}
                    placeholder="Released/Issued By"
                  />
                </Form.Group>
              </Col>
              <Col md={6}>
                <Form.Group className="mb-3">
                  <Form.Label>Date</Form.Label>
                  <Form.Control
                    type="date"
                    value={currentReturn.date}
                    onChange={(e) => setCurrentReturn({ ...currentReturn, date: e.target.value })}
                  />
                </Form.Group>
              </Col>
            </Row>

            {/* Items Section */}
            <Card className="mb-3">
              <Card.Header>
                <Card.Title className="mb-0">Items</Card.Title>
              </Card.Header>
              <Card.Body>
                <Row className="mb-3">
                  <Col md={3}>
                    <Form.Group className="mb-0">
                      <Form.Label className="small">Date Acquired *</Form.Label>
                      <Form.Control
                        type="date"
                        value={newItem.date_acquired}
                        onChange={(e) => setNewItem({ ...newItem, date_acquired: e.target.value })}
                        size="sm"
                      />
                    </Form.Group>
                  </Col>
                  <Col md={3}>
                    <Form.Group className="mb-0">
                      <Form.Label className="small">Item No. *</Form.Label>
                      <Form.Control
                        value={newItem.item_no}
                        onChange={(e) => setNewItem({ ...newItem, item_no: e.target.value })}
                        placeholder="Item No."
                        size="sm"
                      />
                    </Form.Group>
                  </Col>
                  <Col md={3}>
                    <Form.Group className="mb-0">
                      <Form.Label className="small">ICS No.</Form.Label>
                      <Form.Control
                        value={newItem.ics_no}
                        onChange={(e) => setNewItem({ ...newItem, ics_no: e.target.value })}
                        placeholder="ICS No."
                        size="sm"
                      />
                    </Form.Group>
                  </Col>
                  <Col md={3} className="d-flex align-items-end">
                    <Button
                      variant="success"
                      size="sm"
                      onClick={handleAddItem}
                      className="w-100"
                    >
                      <i className="bi bi-plus"></i> Add Item
                    </Button>
                  </Col>
                </Row>

                <Row className="mb-3">
                  <Col md={6}>
                    <Form.Group className="mb-0">
                      <Form.Label className="small">Description *</Form.Label>
                      <Form.Control
                        value={newItem.description}
                        onChange={(e) => setNewItem({ ...newItem, description: e.target.value })}
                        placeholder="Item Description"
                        size="sm"
                      />
                    </Form.Group>
                  </Col>
                  <Col md={3}>
                    <Form.Group className="mb-0">
                      <Form.Label className="small">Amount</Form.Label>
                      <Form.Control
                        type="number"
                        value={newItem.amount}
                        onChange={(e) => setNewItem({ ...newItem, amount: parseFloat(e.target.value) || 0 })}
                        placeholder="0.00"
                        size="sm"
                      />
                    </Form.Group>
                  </Col>
                  <Col md={3}>
                    <Form.Group className="mb-0">
                      <Form.Label className="small">Condition</Form.Label>
                      <Form.Select
                        value={newItem.condition}
                        onChange={(e) => setNewItem({ ...newItem, condition: e.target.value })}
                        size="sm"
                      >
                        <option value="Good">Good</option>
                        <option value="Fair">Fair</option>
                        <option value="Poor">Poor</option>
                      </Form.Select>
                    </Form.Group>
                  </Col>
                </Row>

                {/* Items Table */}
                {currentReturn.items.length > 0 && (
                  <div className="table-responsive mt-3">
                    <Table striped size="sm">
                      <thead>
                        <tr>
                          <th>Date Acquired</th>
                          <th>Item No.</th>
                          <th>ICS No.</th>
                          <th>Description</th>
                          <th>Amount</th>
                          <th>Condition</th>
                          <th>Action</th>
                        </tr>
                      </thead>
                      <tbody>
                        {currentReturn.items.map((item, index) => (
                          <tr key={index}>
                            <td>{item.date_acquired}</td>
                            <td>{item.item_no}</td>
                            <td>{item.ics_no}</td>
                            <td>{item.description}</td>
                            <td>₱{item.amount.toFixed(2)}</td>
                            <td>{item.condition}</td>
                            <td>
                              <Button
                                variant="danger"
                                size="sm"
                                onClick={() => handleRemoveItem(index)}
                              >
                                <i className="bi bi-trash"></i>
                              </Button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </Table>
                  </div>
                )}
              </Card.Body>
            </Card>
          </Form>
        </Modal.Body>
        <Modal.Footer>
          <Button variant="secondary" onClick={() => setShowModal(false)}>
            Cancel
          </Button>
          <Button variant="primary" onClick={handleSave}>
            Save
          </Button>
        </Modal.Footer>
      </Modal>

      {/* View Modal */}
      {selectedReturn && (
        <Modal show={showViewModal} onHide={() => setShowViewModal(false)} size="lg">
          <Modal.Header closeButton>
            <Modal.Title>Property Return Slip - {selectedReturn.prs_no}</Modal.Title>
          </Modal.Header>
          <Modal.Body>
            <Row className="mb-3">
              <Col md={6}>
                <p><strong>Entity Name:</strong> {selectedReturn.entity_name}</p>
              </Col>
              <Col md={6}>
                <p><strong>Fund Cluster:</strong> {selectedReturn.fund_cluster}</p>
              </Col>
            </Row>
            <Row className="mb-3">
              <Col md={6}>
                <p><strong>Return Reason:</strong> {selectedReturn.return_reason}</p>
              </Col>
              <Col md={6}>
                <p><strong>Date:</strong> {selectedReturn.date}</p>
              </Col>
            </Row>

            <h5>Items</h5>
            <div className="table-responsive">
              <Table striped>
                <thead>
                  <tr>
                    <th>Date Acquired</th>
                    <th>Item No.</th>
                    <th>ICS No.</th>
                    <th>Description</th>
                    <th>Amount</th>
                    <th>Condition</th>
                  </tr>
                </thead>
                <tbody>
                  {selectedReturn.items.map((item, index) => (
                    <tr key={index}>
                      <td>{item.date_acquired}</td>
                      <td>{item.item_no}</td>
                      <td>{item.ics_no}</td>
                      <td>{item.description}</td>
                      <td>₱{item.amount.toFixed(2)}</td>
                      <td>{item.condition}</td>
                    </tr>
                  ))}
                </tbody>
              </Table>
            </div>
          </Modal.Body>
          <Modal.Footer>
            <Button variant="secondary" onClick={() => setShowViewModal(false)}>
              Close
            </Button>
          </Modal.Footer>
        </Modal>
      )}

      <Toast
        message={toastMessage}
        type={toastType}
        show={showToast}
        onClose={() => setShowToast(false)}
      />
    </Container>
  );
};

export default PropertyReturnSlip;
